/**
 * generated by stackra gen from src/config/seo.config.ts (og), src/config/theming.config.ts (logo),
 * assets/public/logo.svg, src/routes/site/site.layout.ts and context.ts — do not edit
 * Purpose: `/og/<kind>/<id>`: the Open Graph image of a site, a page or a product, rendered on the
 *          Worker from the site's colours over the `acme` theme and the logo mark, cached at the
 *          edge for `og.cacheSeconds`.
 * Boundary: reads through the same route context and public clients as every loader, with the same
 *           cache profiles; an unknown kind or id is a 404. An image is a file, not a page, so its
 *           shared caching does not touch the HTML rule.
 * Runtime: worker
 */
import { routeContext } from "@stackra/navigation/react";
import { OgKind, SeoConfig } from "@stackra/seo";
import { renderOgImage } from "@stackra/seo/server";
import type { Route } from "./+types/og-image";
import { GetProductBySlugQuery } from "#stackra/clients/commerce";
import { GetDocumentQuery } from "#stackra/clients/experience";
import { CacheProfile } from "#src/enums/cache-profile.enum";
import { SiteLayout } from "#src/routes/site/site.layout";
import logo from "#assets/public/logo.svg?raw";
import { routeKeys } from "../context";

/** The PNG of one kind and id, or 404. */
export async function loader(args: Route.LoaderArgs) {
  const ctx = routeContext(args, routeKeys);
  const og = ctx.config(SeoConfig).og;
  const kind = og.kinds.find((code) => code === args.params.kind);
  if (!kind) return new Response(null, { status: 404 });
  const { site } = await ctx.layout(SiteLayout);

  let title = site.name;
  let image: string | undefined;
  if (kind === OgKind.Product) {
    const product = await ctx
      .query(GetProductBySlugQuery, { slug: args.params.id }, { cache: CacheProfile.Catalogue })
      .catch(() => null);
    if (!product) return new Response(null, { status: 404 });
    title = product.title;
    image = product.images[0]?.url;
  } else if (kind === OgKind.Page) {
    const page = await ctx.query(
      GetDocumentQuery,
      { path: `/${args.params.id}` },
      { cache: CacheProfile.Page },
    );
    title = page?.seo.title ?? site.name;
  }

  const png = await renderOgImage({
    template: kind,
    width: og.width,
    height: og.height,
    title,
    siteName: site.name,
    dir: site.dir,
    brand: site.brand,
    logo,
    ...(image ? { image } : {}),
  });
  return new Response(png, {
    headers: {
      "Content-Type": "image/png",
      "Cache-Control": `public, max-age=0, s-maxage=${og.cacheSeconds}`,
    },
  });
}
